#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
using namespace std;

const int N = 33;
const long long MOD = 1000000007;

struct Matrix {
    long long mat[N][N];
    int size;
    void clear() {
        memset(mat, 0, sizeof(mat));
    }
    void identity() {
        clear();
        for (int i = 0; i < size; ++i)
            mat[i][i] = 1;
    }
    Matrix operator*(const Matrix &b) const {
        Matrix res;
        res.size = size;
        res.clear();
        for (int i = 0; i < size; ++i)
            for (int j = 0; j < size; ++j)
                for (int k = 0; k < size; ++k)
                    res.mat[i][j] = (res.mat[i][j] + mat[i][k] * b.mat[k][j]) % MOD;
        return res;
    }
};

long long n, K;
int r;
vector<Matrix> baseOne, baseTwo, rotRight, rotLeft;

long long readLong() {
    long long x; cin >> x; return x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    n = readLong();
    K = readLong();
    r = K + 1;

    baseOne.resize(r);
    baseTwo.resize(r);
    rotRight.resize(r);
    rotLeft.resize(r);

    for (int i = 0; i < r; ++i) {
        baseOne[i].size = r;
        baseOne[i].clear();
        for (int j = 0; j < r; ++j)
            baseOne[i].mat[i][j] = 1;
        if (i > 0) {
            for (int j = 0; j < r; ++j)
                baseOne[i].mat[i][j] = 1;
        }
    }

    for (int i = 0; i < r; ++i) {
        rotRight[i].size = r;
        rotRight[i].clear();
        if (i == 1) {
            rotRight[i].clear();
            rotRight[i].mat[0][0] = 1;
            rotRight[i].mat[1][K] = 1;
            for (int j = 2; j <= K; ++j)
                rotRight[i].mat[j][j - 1] = 1;
        } else if (i > 1) {
            rotRight[i] = rotRight[1] * rotRight[i - 1];
        } else {
            rotRight[i].identity();
        }
    }

    for (int i = 0; i < r; ++i) {
        rotLeft[i].size = r;
        rotLeft[i].clear();
        if (i == 1) {
            rotLeft[i].clear();
            rotLeft[i].mat[0][0] = 1;
            rotLeft[i].mat[K][1] = 1;
            for (int j = 2; j <= K; ++j)
                rotLeft[i].mat[j - 1][j] = 1;
        } else if (i > 1) {
            rotLeft[i] = rotLeft[i - 1] * rotLeft[1];
        } else {
            rotLeft[i].identity();
        }
    }

    baseTwo[1].size = r;
    baseTwo[1].identity();
    for (int i = 1; i <= K; ++i)
        baseTwo[1] = baseOne[i] * baseTwo[1];

    vector<long long> num;
    long long tempN = n;
    while (tempN > 0) {
        num.push_back(tempN % K);
        tempN /= K;
    }
    reverse(num.begin(), num.end());

    for (size_t i = 2; i < num.size(); ++i) {
        baseTwo[i].size = r;
        baseTwo[i].identity();
        for (int j = 0; j < K; ++j)
            baseTwo[i] = rotRight[j] * baseTwo[i - 1] * rotLeft[j] * baseTwo[i];
    }

    Matrix result;
    result.size = r;
    result.identity();

    int position = 0;
    for (size_t i = 0; i < num.size(); ++i) {
        long long count = num[i];
        if (i == num.size() - 1) {
            for (long long j = 0; j < count; ++j) {
                result = baseOne[position % K + 1] * result;
                position++;
            }
        } else {
            for (long long j = 0; j < count; ++j) {
                result = rotRight[position % K] * baseTwo[num.size() - i - 2] * rotLeft[position % K] * result;
                position++;
            }
        }
    }

    long long answer = 1;
    for (int i = 1; i <= K; ++i)
        for (int j = 0; j < r; ++j)
            answer = (answer + result.mat[i][0]) % MOD;

    cout << answer % MOD << "\n";

    return 0;
}
